package me.cryo.zombierool.gameplay;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.core.BlockPos;
import me.cryo.zombierool.config.SpecialEnemyConfig;
@net.minecraftforge.fml.common.Mod.EventBusSubscriber(modid="zombierool")
public final class MiniBossTransitions {
    private static final java.util.Map<ServerLevel,String> FIRED=new java.util.WeakHashMap<>();
    private static boolean activatorActive(ServerLevel level,BlockPos pos){var block=level.getBlockState(pos).getBlock();return block instanceof me.cryo.zombierool.block.ActivatorBlock?me.cryo.zombierool.config.GlobalSwitchState.isActivated(level):block instanceof me.cryo.zombierool.block.AbstractActivatorBlock activator&&me.cryo.zombierool.config.MultiReceptorState.isActivated(level,activator.signalChannel());}
    public static void reset(ServerLevel level){FIRED.remove(level);}
    public static boolean evaluate(ServerLevel level){if(!WaveManager.isGameRunning())return false;var c=SpecialEnemyConfig.get(level);String mode=c.getString("bossSwitchTrigger"),to=c.getString("bossSwitchTarget");if(mode.equals("none")||!me.cryo.zombierool.config.MiniBossDefinitions.contains(to))return false;String signature=mode+":"+to+":"+c.getInt("bossSwitchWave")+":"+c.getInt("bossSwitchX")+":"+c.getInt("bossSwitchY")+":"+c.getInt("bossSwitchZ")+":"+c.getString("bossSwitchSoulIds");if(signature.equals(FIRED.get(level)))return false;var pos=new BlockPos(c.getInt("bossSwitchX"),c.getInt("bossSwitchY"),c.getInt("bossSwitchZ"));boolean active=switch(mode){case "wave"->WaveManager.getCurrentWave()>=c.getInt("bossSwitchWave");case "power"->me.cryo.zombierool.config.GlobalSwitchState.isActivated(level);case "activator"->level.hasChunkAt(pos)&&activatorActive(level,pos);case "soul_checker"->!c.getString("bossSwitchSoulIds").isBlank()?me.cryo.zombierool.block.system.SoulObjectiveRegistry.get(level).allComplete(c.getString("bossSwitchSoulIds")):level.hasChunkAt(pos)&&level.getBlockEntity(pos) instanceof me.cryo.zombierool.block.system.SoulCompletionSystem.Checker checker&&checker.enabled&&me.cryo.zombierool.block.system.SoulObjectiveRegistry.get(level).allComplete(checker.ids);default->false;};if(!active)return false;FIRED.put(level,signature);var update=new net.minecraft.nbt.CompoundTag();update.putString("type",to);SpecialEnemyConfig.update(level,update);return true;}
    @net.minecraftforge.eventbus.api.SubscribeEvent public static void tick(net.minecraftforge.event.TickEvent.ServerTickEvent event){if(event.phase==net.minecraftforge.event.TickEvent.Phase.END&&event.getServer().getTickCount()%20==0)for(var level:event.getServer().getAllLevels())evaluate(level);}
}
